# Dedicated module may be used for parsing command line options specific for given application.
# It is required to run in before calling uvicorn.run() to not mix with uvicorn command line parameters processing.
# We can make it generic by following convention:
# 1) file is named cmd_line
# 2) it has entry point parse_options(logger)
# 3) returned value is single dict
import argparse
import os
from .exceptions import InvalidProxyMngrCmdArgsException


# flake8: noqa: C901
def parse_mngr_options(config_default_name="proxy.cfg"):
    parser = argparse.ArgumentParser()
    parser.add_argument("-p", "--port", help="define port for proxy manager server (default: 443 or 80)", default=9955)
    parser.add_argument("--ueproxy_ports_range", nargs=2,
                        help="define port range for ueproxy to be started by proxy manager service (i.e. 8000 8100)",
                        required=True)
    parser.add_argument("--ueproxy_config",
                        help=f"config file for ueproxy to be started by proxy manager service(default: {config_default_name}), "
                             f"if you provide directory we will search {config_default_name} there.",
                        required=False,
                        default=config_default_name)
    parser.add_argument("--ssl_keyfile", help="file containing proxy manager server private key", required=False)
    parser.add_argument("--ssl_certfile", help="file containing proxy manager server certificate", required=False)
    parser.add_argument("--ssl_client_certbundle",
                        help="client root certificates for https dialog between UE-proxy manager and UE-proxy",
                        required=False)
    parser.add_argument("--dev_https", help="use development time certificate (self-signed)", action='store_true')
    parser.add_argument("--update_period",
                        help="Define time period for autoupdating ueproxy - "
                             "format: 1h -> 1hour, 1d -> 1day, 1w -> 1week, 1m -> 1month",
                        default="1d")
    parser.add_argument("--update_plugin", help="Define plugins for autoupdating ueproxy",
                        required=False, action='append')
    parser.add_argument("--update_format", help="Define plugins for autoupdating ueproxy",
                        required=False, default="pyz")
    parser.add_argument("--logs_storage_limit", help="Number of maximum instances of logs that manager can store",
                        required=False, default=50)
    parser.add_argument("--logs_storage_duration", help="Number of days for which logs will be stored",
                        required=False, default=7)
    parser.add_argument("--proxy_mngr_artifactory", help="Link to artifactory", required=False)
    parser.add_argument("--ueproxy_naa_protocol",
                        help="NAA protocol for ueproxy to be started by proxy manager service(default: usb_byte)",
                        required=False, choices=['usb_byte', 'socketio'], default="socketio")
    parser.add_argument("--at_ue_manager", help="allow to run AT UE Manager via taf.ue.proxy", action="store_true")
    parser.add_argument("--stream_logs", help="allow to stream logs into /ui page", action="store_true")
    parser.add_argument("--pyz_start_timeout", help="Timeout for ueproxy pyz start", required=False, default=60)

    args = parser.parse_args()

    if os.path.isdir(args.ueproxy_config):
        args.ueproxy_config = os.path.join(args.ueproxy_config, config_default_name)

    start, stop = args.ueproxy_ports_range
    if int(start) <= 0 or int(stop) < int(start):
        raise InvalidProxyMngrCmdArgsException("Invalid ueproxy ports range!")
    elif int(args.port) in range(int(start), int(stop)):
        raise InvalidProxyMngrCmdArgsException("Proxy manager port within ueproxy ports range!")

    if args.dev_https:
        args.ssl_keyfile = os.path.join(os.path.dirname(__file__), "certificates",
                                        "for_development", "localhost_dev.key")
        args.ssl_certfile = os.path.join(os.path.dirname(__file__), "certificates",
                                         "for_development", "localhost_dev.crt")
        args.ssl_client_certbundle = os.path.join(os.path.dirname(__file__), "certificates",
                                                  "for_development", "RootCertsBundle.crt")

    if args.ssl_keyfile and args.port == 80:  # HTTPS wanted
        args.port = 443
    elif args.port == 443:
        args.port = 80

    return args
